def transform(g):
    import numpy as np
    a=np.array(g); h,w=a.shape; out=a.copy()
    seen=np.zeros_like(a,bool)
    from collections import deque
    for i in range(h):
        for j in range(w):
            if a[i,j]==2 and not seen[i,j]:
                q=deque([(i,j)]); seen[i,j]=True; comp=[]
                while q:
                    y,x=q.popleft(); comp.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and a[ny,nx]==2 and not seen[ny,nx]:
                            seen[ny,nx]=True; q.append((ny,nx))
                ys=[c[0] for c in comp]; xs=[c[1] for c in comp]
                y0,y1,x0,x1=min(ys),max(ys),min(xs),max(xs)
                # check full rectangle border
                ok=True
                for y in range(y0,y1+1):
                    for x in range(x0,x1+1):
                        if (y in(y0,y1) or x in(x0,x1)) and a[y,x]!=2: ok=False
                if ok and y1-y0>=2 and x1-x0>=2:
                    for y in range(y0+1,y1):
                        for x in range(x0+1,x1):
                            if a[y,x]==0: out[y,x]=8
    return out.tolist()

